// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call sudicideAnyone() as the owner
        vm.prank(address(this));
        try c.sudicideAnyone() {
            // Reference: selfdestruct occurs; bug: revert is caught by try/catch? No, revert is caught by try/catch, but that would make the catch execute.
            // Actually, for the reference, selfdestruct doesn't revert, so we enter the try block.
            // For the bug, revert() causes the catch block to execute.
            // So we need to determine divergence based on state after the call.
        } catch {
            // Bug goes here, reference does not.
        }
        // After the call, check if contract bytecode exists (reference self-destructs, so code.length == 0; bug does not self-destruct, so code.length > 0)
        assertTrue(address(c).code.length == 0, "Reference should self-destruct");
    }
}

