pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        vm.prank(owner);
        c.sudicideAnyone();
        // After self-destruct, the contract no longer has code, so calling again should revert
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        // Reference: self-destructed, so second call reverts => ok == false
        // Bug: no self-destruct, so second call succeeds => ok == true
        assertTrue(!ok);
    }
}

