pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        // First call: should self-destruct in reference, revert in buggy
        c.sudicideAnyone();
        // Second call: in reference, contract is gone so call reverts. In buggy, contract still exists so call succeeds.
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false, "buggy version does not self-destruct; second call should revert");
    }
}

